// Bundles the shared Compass agent layer (src/lib/agent + the domain modules it uses) into
// one self-contained ES module for the Supabase Edge Function (Deno):
//
//   npm run build:shared   ->  supabase/functions/_shared/compass-agent.js
//
// The output is committed; supabase/tests/shared-bundle.test.ts fails if it's stale.

import { build } from 'esbuild';
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

export const SHARED_OUTFILE = 'supabase/functions/_shared/compass-agent.js';

const BANNER = [
  '// GENERATED by `npm run build:shared` from src/lib/agent. Do not edit.',
  '// @ts-self-types="./compass-agent.d.ts"',
].join('\n');

export const sharedBuildOptions = {
  entryPoints: ['src/lib/agent/index.ts'],
  bundle: true,
  format: 'esm',
  platform: 'neutral',
  target: 'es2022',
  charset: 'utf8',
  legalComments: 'none',
  banner: { js: BANNER },
  logLevel: 'warning',
};

/** Bundle text with normalised line endings. */
export async function buildSharedBundle() {
  const out = await build({ ...sharedBuildOptions, write: false, outfile: SHARED_OUTFILE });
  return out.outputFiles[0].text.replace(/\r\n/g, '\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  await writeFile(SHARED_OUTFILE, await buildSharedBundle());
  console.log(`wrote ${SHARED_OUTFILE}`);
}
